package io.colorsand.core

/** A puzzle: a numbered starting [board]. */
data class Level(val number: Int, val board: Board) {
    init {
        require(board.tubes.isNotEmpty()) { "Level $number has no tubes" }
        val capacity = board.tubes.first().capacity
        require(board.tubes.all { it.capacity == capacity }) { "Level $number mixes tube capacities" }
        board.colorCounts().forEach { (color, count) ->
            require(count == capacity) { "Level $number has $count units of $color, expected $capacity" }
        }
        val colors = board.colorCounts().size
        require(board.tubes.size >= colors) { "Level $number has $colors colors but only ${board.tubes.size} tubes" }
    }

    val capacity: Int get() = board.tubes.first().capacity
    val colorCount: Int get() = board.colorCounts().size

    companion object {
        fun parse(number: Int, capacity: Int, vararg tubes: String): Level = Level(number, Board.parse(capacity, *tubes))
    }
}
