private val Sand = Color(0xFFF4E4C1)
private val Night = Color(0xFF1B1F3B)
private val Dusk = Color(0xFF3B2F5C)

private val colors = darkColorScheme(
    primary = Sand,
    onPrimary = Night,
    secondary = Color(0xFFFFD54F),
    background = Night,
    surface = Color(0xFF2A2F55),
    onSurface = Color.White,
)

/** The whole game: level header, tubes, controls, and the level-complete card. */
@Composable
fun App(store: ProgressStore) {
    val game = rememberSaveable(saver = GameController.saver(store)) { GameController(store) }
    MaterialTheme(colorScheme = colors) {
        Box(
            Modifier
                .fillMaxSize()
                .background(Brush.verticalGradient(listOf(Night, Dusk)))
                .windowInsetsPadding(WindowInsets.safeDrawing),
        ) {
            Column(
                Modifier.fillMaxSize().padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                Header(game)
                Board(game, Modifier.weight(1f).fillMaxWidth())
                NoticeLine(game)
                Controls(game)
            }
            if (game.isSolved) {
                Box(Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.45f)))
                LevelComplete(game, Modifier.align(Alignment.Center))
            }
        }
    }
}

@Composable
private fun Header(game: GameController) {
    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
        Text("Level ${game.levelNumber}", color = Sand, fontSize = 24.sp, fontWeight = FontWeight.Bold)
        Spacer(Modifier.weight(1f))
        Text("Moves ${game.moveCount}", color = Color.White.copy(alpha = 0.7f), fontSize = 16.sp)
    }
}

@Composable
private fun Board(game: GameController, modifier: Modifier) {
    val tubes = game.board.tubes
    BoxWithConstraints(modifier, contentAlignment = Alignment.Center) {
        val rows = rowCount(tubes.size)
        val perRow = ceil(tubes.size / rows.toFloat()).toInt()
        // Each tube gets a column of the width; leave room between rows for the lift and the gap.
        val byWidth = maxWidth / perRow * 0.68f
        val byHeight = maxHeight / rows / (TUBE_ASPECT + 0.9f)
        val tubeWidth = min(min(byWidth.value, byHeight.value), 64f).dp
        Column(verticalArrangement = Arrangement.spacedBy(tubeWidth * 0.7f)) {
            tubes.indices.chunked(perRow).forEach { row ->
                Row(horizontalArrangement = Arrangement.spacedBy(tubeWidth * 0.4f)) {
                    for (i in row) {
                        TubeView(
                            tube = tubes[i],
                            highlight = highlightOf(game, i),
                            width = tubeWidth,
                            onTap = { game.tap(i) },
                        )
                    }
                }
            }
        }
    }
}

/** One row for up to 6 tubes, then as many rows as needed for at most 7 per row. */
internal fun rowCount(tubes: Int): Int = if (tubes <= 6) 1 else ceil(tubes / 7f).toInt().coerceAtLeast(2)

private fun highlightOf(game: GameController, tube: Int): TubeHighlight = when {
    game.selected == tube -> TubeHighlight.SELECTED
    game.hint?.from == tube -> TubeHighlight.HINT_FROM
    game.hint?.to == tube -> TubeHighlight.HINT_TO
    else -> TubeHighlight.NONE
}

@Composable
private fun NoticeLine(game: GameController) {
    val text = when {
        game.isSolved -> null
        game.isStuck -> "No moves left. Undo or restart."
        game.notice == Notice.DEAD_END -> "This can't be solved from here. Undo or restart."
        game.notice == Notice.NO_HINT -> "No hint found. Try a few moves."
        game.hint != null -> "Hint: pour the raised tube into the other glowing one."
        else -> null
    }
    Box(Modifier.height(40.dp), contentAlignment = Alignment.Center) {
        if (text != null) Text(text, color = Color(0xFFFFD54F), textAlign = TextAlign.Center, fontSize = 14.sp)
    }
}

@Composable
private fun Controls(game: GameController) {
    Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
        OutlinedButton(onClick = game::undo, enabled = game.canUndo && !game.isSolved) { Text("Undo") }
        OutlinedButton(onClick = game::restart, enabled = game.canUndo && !game.isSolved) { Text("Restart") }
        Button(onClick = game::showHint, enabled = !game.isSolved && !game.isStuck) { Text("Hint") }
    }
}

@Composable
private fun LevelComplete(game: GameController, modifier: Modifier) {
    Surface(modifier.widthIn(max = 320.dp).padding(24.dp), shape = RoundedCornerShape(20.dp), tonalElevation = 8.dp) {
        Column(Modifier.padding(24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
            Text("Level ${game.levelNumber} solved!", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = Sand)
            Spacer(Modifier.height(8.dp))
            Text("${game.moveCount} moves", color = Color.White.copy(alpha = 0.7f))
            Spacer(Modifier.height(20.dp))
            Button(
                onClick = game::nextLevel,
                colors = ButtonDefaults.buttonColors(containerColor = Sand, contentColor = Night),
            ) { Text("Next level") }
        }
    }
}
